from collections import OrderedDict

def cache_sim(capacity, ttl, ops):
    cache = OrderedDict()  # key -> (value, write_time)
    results = []

    def is_expired(key, t):
        if key not in cache:
            return True
        _, wt = cache[key]
        return t >= wt + ttl

    for op in ops:
        kind = op[0]
        t = op[1]
        if kind == 'put':
            key = op[2]
            value = op[3]
            if key in cache:
                if is_expired(key, t):
                    del cache[key]
                else:
                    del cache[key]
            if len(cache) >= capacity:
                # need to remove expired entries first? Actually eviction rule:
                # if key is absent (not present or expired) and cache already holds capacity entries,
                # evict LRU. But expired entries still occupy slot until accessed/removed.
                # We must evict LRU (which could be an expired one) - eviction just pops oldest.
                oldest_key, _ = next(iter(cache.items()))
                del cache[oldest_key]
            cache[key] = (value, t)
        elif kind == 'get':
            key = op[2]
            if key in cache and not is_expired(key, t):
                value, wt = cache[key]
                del cache[key]
                cache[key] = (value, wt)
                results.append(value)
            else:
                if key in cache:
                    del cache[key]
                results.append(-1)
    return results

